        .def_property_readonly("last_next_n_token", [](const SequenceMetadata &self) { return self.mtp.draft_tokens; })
        .def_readwrite("so_status", &SequenceMetadata::so_status)
        .def_readonly("so_matcher", &SequenceMetadata::so_matcher);

